exercises.solution:
async function retry(fn, attempts, delayMs) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn(i);
    } catch (err) {
      lastError = err;
      if (i < attempts - 1) {
        await new Promise((resolve) => setTimeout(resolve, delayMs * 2 ** i));
      }
    }
  }
  throw lastError;
}

